function envv121(string $path): array { $out=[]; foreach(file($path,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $row){$row=trim($row);if($row===''||$row[0]==='#')continue;$p=strpos($row,'=');if($p===false)continue;$k=trim(substr($row,0,$p));$v=trim(substr($row,$p+1));if(strlen($v)>=2&&(($v[0]==='"'&&$v[-1]==='"')||($v[0]==="'"&&$v[-1]==="'")))$v=substr($v,1,-1);$out[$k]=$v;}return$out; }
function cfgv121(array $env,string $db):array{$c=['host'=>$env['DB_HOST']??'127.0.0.1','port'=>$env['DB_PORT']??'3306','username'=>$env['DB_USERNAME']??'','password'=>$env['DB_PASSWORD']??''];$pool=json_decode($env['COMPANY_DB_POOL_JSON']??'',true);if(is_array($pool))foreach($pool as$x){if(is_array($x)&&($x['database']??$x['db']??'')===$db){foreach(['host','port','username','password']as$k)if(!empty($x[$k]))$c[$k]=$x[$k];break;}}return$c;}
$root=rtrim((string)(getenv('PLANEX_ROOT')?:($argv[1]??'')),'/');if($root===''||!is_file($root.'/.env'))throw new RuntimeException('PLANEX_ROOT invalid');$env=envv121($root.'/.env');$db='spugovxsim_1';$c=cfgv121($env,$db);$pdo=new PDO('mysql:host='.$c['host'].';port='.$c['port'].';dbname='.$db.';charset=utf8mb4',$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);if($pdo->query('SELECT DATABASE()')->fetchColumn()!==$db)throw new RuntimeException('Unexpected DB');
$tableExists=static function(PDO$p,string$t):int{$s=$p->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$s->execute([$t]);return(int)$s->fetchColumn();};$countIf=static function(PDO$p,string$t)use($tableExists):int{return$tableExists($p,$t)?(int)$p->query('SELECT COUNT(*) FROM `'.$t.'`')->fetchColumn():0;};
$migration=0;if($tableExists($pdo,'schema_migrations')){$s=$pdo->prepare('SELECT COUNT(*) FROM schema_migrations WHERE migration=?');$s->execute(['121_closing_document_evidence_overrides.sql']);$migration=(int)$s->fetchColumn();}
