$snapshot=['bank_transactions'=>$countIf($pdo,'bank_transactions'),'documents'=>$countIf($pdo,'documents'),'closing_links'=>$countIf($pdo,'finance_closing_document_links'),'manual_table'=>$tableExists($pdo,'finance_closing_document_manual_statuses'),'manual_rows'=>$countIf($pdo,'finance_closing_document_manual_statuses'),'requirement_exception_table'=>$tableExists($pdo,'finance_closing_document_requirement_exceptions'),'requirement_exception_rows'=>$countIf($pdo,'finance_closing_document_requirement_exceptions'),'is_edo_column'=>$col,'migration_121_applied'=>$migration];
